#!/usr/bin/env node
/**
 * Mirrors the Claude Platform (Anthropic) API's OpenAPI spec into ../specs/.
 *
 * Anthropic's official SDKs are generated by Stainless from one OpenAPI
 * document. Each SDK repository commits that document, gzipped, as
 * `scripts/mock-spec.json.gz` (its mock server reads it); before September
 * 2026 `.stats.yml` linked it as `openapi_spec_url` instead. Only that one
 * file is downloaded, straight from raw.githubusercontent.com — the upstream
 * repository is never cloned.
 *
 * Usage:
 *   node fetch-specs.ts
 *
 * Specs are saved to:
 *   ../specs/openapi.json
 */

import { mkdirSync } from "fs";
import { writeFile } from "fs/promises";
import { gunzipSync } from "zlib";

/** Upstream repository, as `<owner>/<repo>`. */
const REPO = "anthropics/anthropic-sdk-typescript";
/** Branch to mirror. */
const REF = "main";
/** Path within {@link REPO}. */
const PATH = "scripts/mock-spec.json.gz";

const SPECS_DIR = "../specs";

mkdirSync(SPECS_DIR, { recursive: true });

async function main() {
  const url = `https://raw.githubusercontent.com/${REPO}/${REF}/${PATH}`;
  console.log(`Fetching ${url}...`);

  const response = await fetch(url);
  if (!response.ok) {
    throw new Error(`Failed to fetch ${url}: ${response.status} ${response.statusText}`);
  }
  const gzipped = new Uint8Array(await response.arrayBuffer());
  const spec = JSON.parse(gunzipSync(gzipped).toString("utf8")) as {
    openapi?: unknown;
    paths?: unknown;
  };
  if (typeof spec.openapi !== "string" || spec.paths === undefined) {
    throw new Error(`${url} is not an OpenAPI document`);
  }

  const outputPath = `${SPECS_DIR}/openapi.json`;
  console.log(`Writing ${outputPath}...`);
  await writeFile(outputPath, JSON.stringify(spec, null, 2) + "\n");

  console.log("Done!");
}

main().catch((err) => {
  console.error("Fatal error:", err);
  process.exit(1);
});
